import React, { useState } from "react";

function AdminPanel({ plants, onAdd, onEdit, onDelete }) {
    const [editing, setEditing] = useState(null);
    const [form, setForm] = useState({
        id: "",
        name: "",
        image: "",
        x: 50,
        y: 50,
        shortDescription: "",
        fullDescription: "",
    });

    const handleEditClick = (plant) => {
        setEditing(plant.id);
        setForm(plant);
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (editing) {
            onEdit(form);
        } else {
            onAdd({ ...form, id: Date.now().toString() });
        }
        setForm({
            id: "",
            name: "",
            image: "",
            x: 50,
            y: 50,
            shortDescription: "",
            fullDescription: "",
        });
        setEditing(null);
    };

    return (
        <div style={{ padding: 20 }}>
            <h2>Админ-панель</h2>
            <form onSubmit={handleSubmit}>
                <input
                    placeholder="Название"
                    value={form.name}
                    onChange={e => setForm({ ...form, name: e.target.value })}
                    required
                />
                <input
                    placeholder="Ссылка на картинку"
                    value={form.image}
                    onChange={e => setForm({ ...form, image: e.target.value })}
                    required
                />
                <input
                    placeholder="X (0-100%)"
                    type="number"
                    value={form.x}
                    onChange={e => setForm({ ...form, x: Number(e.target.value) })}
                    required
                    min="0"
                    max="100"
                />
                <input
                    placeholder="Y (0-100%)"
                    type="number"
                    value={form.y}
                    onChange={e => setForm({ ...form, y: Number(e.target.value) })}
                    required
                    min="0"
                    max="100"
                />
                <input
                    placeholder="Краткое описание"
                    value={form.shortDescription}
                    onChange={e => setForm({ ...form, shortDescription: e.target.value })}
                    required
                />
                <textarea
                    placeholder="Полное описание"
                    value={form.fullDescription}
                    onChange={e => setForm({ ...form, fullDescription: e.target.value })}
                    required
                />
                <button type="submit">{editing ? "Сохранить" : "Добавить"}</button>
                {editing && <button onClick={() => setEditing(null)}>Отмена</button>}
            </form>
            <h3>Список заводов</h3>
            <ul>
                {plants.map((plant) => (
                    <li key={plant.id}>
                        <b>{plant.name}</b>
                        <button onClick={() => handleEditClick(plant)}>Редактировать</button>
                        <button onClick={() => onDelete(plant.id)}>Удалить</button>
                    </li>
                ))}
            </ul>
        </div>
    );
}

export default AdminPanel;
